def write_all(write, data):
    total = 0
    while data:
        bytes_written = write(data)
        if bytes_written <= 0:
            raise OSError("Failed to write data")
        total += bytes_written
        data = data[bytes_written:]
    return total

def attach_readings(sensors, latest):
    fresh_dicts = []
    for sensor in sensors:
        sensor_id = sensor["id"]
        latest_value = latest.get(sensor_id, None)
        fresh_dict = {
            "id": sensor_id,
            "value": latest_value if latest_value is not None else sensor["value"]
        }
        fresh_dicts.append(fresh_dict)
    return fresh_dicts

def coerce_field(value):
    if value is None:
        return None
    elif isinstance(value, bool):
        return "true" if value else "false"
    elif isinstance(value, str):
        return value.strip()
    elif isinstance(value, (int, float)):
        return str(value)
    else:
        raise TypeError("Unsupported type for coercion")

def total_coverage(spans):
    if not spans:
        return 0
    if any(span[0] >= span[1] for span in spans):
        raise ValueError("Reversed intervals are not allowed")
    spans.sort()
    coverage = 0
    start = spans[0][0]
    for end, _ in spans:
        coverage += end - start
        start = end
    return coverage

def ttl_lookup(cache, key, now, fetch, ttl):
    if key in cache:
        entry = cache[key]
        if entry['expires_at'] > now:
            return entry['value']
    try:
        result = fetch(key)
        if result is not None:
            cache[key] = {'expires_at': now + ttl, 'value': result}
            return result
    except Exception as e:
        print(f"Error fetching {key}: {e}")
        return None

