def first_unique(values, count):
    seen = set()
    unique_values = []
    for value in values:
        if value not in seen:
            seen.add(value)
            unique_values.append(value)
            if len(unique_values) == count:
                break
    return unique_values

def encode_frame(payload):
    if len(payload) > 65535:
        raise ValueError("Length cannot exceed 65535")
    return payload.encode("utf-8") + bytes([len(payload) & 0xFF, (len(payload) >> 8) & 0xFF])

