from contextlib import contextmanager

@contextmanager
def capture_append(target):
    try:
        target.append("data")
        yield target
    except Exception as e:
        target.clear()
        raise e

def find_matches(records, columns, needle):
    def is_match(record, needle):
        for column in columns:
            if column not in record or not isinstance(record[column], str):
                return False
            if needle.lower() in record[column].lower():
                return True
        return False

    return (record for record in records if is_match(record, needle))

def pad_rows(rows, width, fill=None):
    if width < 0:
        raise ValueError("width must be non-negative")
    for row in rows:
        if len(row) < width:
            row.extend([fill] * (width - len(row)))
        yield row

import curses
import time

def main(stdscr):
    curses.curs_set(0)
    stdscr.keypad(True)
    stdscr.timeout(120)

    snake = [(0, 0)]
    direction = (0, 1)
    food = (0, 0)
    score = 0

    def draw_snake():
        for pos in snake:
            stdscr.addch(pos[0], pos[1], curses.ACS_CKBOARD)

    def draw_food():
        stdscr.addch(food[0], food[1], curses.ACS_PI)

    def move_snake():
        new_head = (snake[0][0] + direction[0], snake[0][1] + direction[1])
        snake.insert(0, new_head)

        if new_head == food:
            score += 1
            food = (random.randint(0, curses.LINES - 1), random.randint(0, curses.WIDTH - 1))
        else:
            snake.pop()

    def handle_input():
        key = stdscr.getch()
        if key == ord('q'):
            return False
        elif key == curses.KEY_UP and direction != (0, 1):
            direction = (0, -1)
        elif key == curses.KEY_DOWN and direction != (0, -1):
            direction = (0, 1)
        elif key == curses.KEY_LEFT and direction != (1, 0):
            direction = (-1, 0)
        elif key == curses.KEY_RIGHT and direction != (-1, 0):
            direction = (1, 0)
        return True

    while True:
        if not handle_input():
            break
        move_snake()
        draw_snake()
        draw_food()
        stdscr.refresh()
        time.sleep(0.1)

if __name__ == "__main__":
    curses.wrapper(main)
